describe("SPEC-RT-006: Runner: one namespace per spec file, delivered to adapters and host", () => {
  let h: Harness;
  beforeAll(async () => {
    h = await createHarness({ configPath: CONFIG_PATH, specPath: SPEC_PATH });
  });
  afterAll(async () => {
    await h.teardown();
  });
  for (const c of CASES) {
    it(c.name, async () => {
      await h.runCase(c, INLINE);
    });
  }
});
